#include <iostream.h>
#include <conio.h>

int main()
{
    clrscr();
    int n, prime = 1;
    cout << "Enter a number (1-32767): ";
    cin >> n;
    if (n < 2)
        prime = 0;
    for (int i = 2; prime && i <= n / i; i++)
        if (n % i == 0)
            prime = 0;
    if (prime)
        cout << "Prime number";
    else
        cout << "Not a prime number";
    getch();
    return 0;
}

