#include <iostream.h>
#include <conio.h>

int main()
{
    clrscr();
    int values[5] = {64, 25, 12, 22, 11};
    for (int i = 0; i < 4; i++)
        for (int j = 0; j < 4 - i; j++)
            if (values[j] > values[j + 1])
            {
                int temp = values[j];
                values[j] = values[j + 1];
                values[j + 1] = temp;
            }
    cout << "Sorted numbers: ";
    for (int k = 0; k < 5; k++)
        cout << values[k] << " ";
    getch();
    return 0;
}

